"""Explain chain records, missing shadow diagnostics, alignment and page lookup."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1729': ('전달 기록 카드에 카드 종류, 이번 전달 장소, 이전 카드 번호를 적어요. 이전 카드 번호를 따라가면 더 오래된 기록을 찾을 수 있어요.', '원인 연결 기록의 세 항목과 저장 전 검사 표시의 이유를 이해합니다.', 'entries의 세 칸에 연결표식·현재 호출기록 번호·이전 원인 번호77을 적고 마지막 칸에서 이전 기록으로 화살표를 그리세요.', ['origin chain은 준비되지 않은 값이 거쳐 온 원인을 연결한 기록이에요. 새 연결을 만들 때 entries라는 세 칸짜리 배열을 채워요. 배열의 번호는0부터 시작하므로 세 칸은 entries[0],entries[1],entries[2]예요.', '첫 칸은 KMSAN_CHAIN_MAGIC_ORIGIN이에요. magic은 마법이 아니라 이 기록이 어떤 형식인지 알아보는 특별한 표식이에요. 둘째 칸은 지금 호출 스택을 저장해 얻은 번호예요. 호출 스택은 어떤 함수들을 거쳐 이 위치에 왔는지 나타내요.', '셋째 칸은 이전 origin의 id예요. 예를 들어 이전 기록 번호가77이면 여기에77을 넣어 이전 원인을 따라갈 연결을 남겨요. 새 데이터 버퍼의 주소를 넣는 칸과는 달라요. 식별자 번호와 실제 데이터 주소를 구별하세요.', '새 기록을 만드는 경로에서는 깊이를1 늘리고 기존 UAF 표시를 유지한 extra bits를 준비해요. UAF는 해제 후 사용과 관련된 표시예요. 새로 저장한 handle에 이 추가 정보를 붙이므로 현재 기록과 연결 깊이를 함께 추적할 수 있어요.', 'entries를 채우는 이 코드는 비계측 코드예요. 즉 값을 썼다는 사실이 검사 정보에 자동으로 반영되지 않을 수 있어요. 실제 세 칸을 채웠어도 KMSAN이 아직 미준비라고 생각하면 정상 기록을 오류로 보고할 수 있어요.', '그래서 저장소인 stack depot에 넘기기 전에 entries 범위를 unpoison해 준비됐다고 알려요. 이것은 실제 세 값을0으로 지우는 일이 아니에요. 채운 값과 검사표를 맞춘 뒤 세 항목을 저장하고 새 식별자를 돌려주는 순서예요.'], [('새 원인 연결의 entries 마지막 칸에는 무엇을 넣나요?', ['새 데이터 버퍼 주소예요', '이전 origin의 id예요'], '정답은 두 번째예요. 세 칸은 연결 표식·현재 호출 기록·이전 id예요. 마지막 칸이 있어야 이전 원인 기록으로 이어갈 수 있어요.'), ('지역 배열 entries를 저장 전에 왜 unpoison하나요?', ['이미 채운 값이라는 사실을 검사 도구에 알려 잘못된 보고를 피하려고 해요', '세 실제 값을 모두0으로 지우려고 해요'], '정답은 첫 번째예요. 비계측 코드의 쓰기는 검사 상태에 자동 반영되지 않을 수 있어요. unpoison은 실제 기록을 지우지 않고 검사 정보를 준비됨으로 맞춰요.')]), 'os1730': ('표시할 검사표가 없으면 새 표를 만드는 대신 돌아갈 수 있어요. 다만 반드시 표가 있어야 한다고 요청한 경우에는 없다는 사실을 알려 줘야 해요.', '검사 정보가 없을 때 checked에 따라 진단이 달라지는 것을 이해합니다.', '연속성 조건이 맞는 미추적 범위에서 checked거짓→반환, checked참→로그·경고 경로를 그리세요.', ['kmsan_internal_set_shadow_origin은 지정 범위의 검사 상태와 원인 정보를 설정하는 함수예요. shadow는 값의 준비 상태를 담는 검사 정보예요. 먼저 메타데이터 범위의 연속성 조건에 대해 경고 검사를 해요.', '그 다음 kmsan_get_metadata로 shadow 주소를 찾아요. 조회 결과가 NULL이면 검사 정보를 쓸 장소가 없다는 뜻이에요. 이 함수는 그 자리에서 새 shadow 메모리를 할당하지 않아요.', 'shadow가 없고 checked가 거짓이면 이 누락에 대한 추가 로그·경고 없이 반환해요. 연속성 확인은 앞에 별도로 있으므로 checked거짓이면 어떤 입력에서도 아무 경고가 없다고 넓혀 말하면 안 돼요. 여기서는 shadow 누락 분기를 따로 보는 것이에요.', 'shadow가 없고 checked가 참이면 pr_err로 오류 설명을 남기고 KMSAN_WARN_ON(true)를 호출해요. 로그에는 shadow가 없어 지정 바이트를 채우지 못한다는 내용이 있어요. 경고 처리에서 정상적으로 돌아오면 뒤의 return으로 끝나요. 실제 경고 정책이 실행을 멈출 가능성과 함수의 코드 순서는 구별해야 해요.', 'checked는 검사표가 없는 범위를 어떻게 진단할지에 관련된 선택이에요. true라고 없는 공간이 만들어지거나 false라고 실제 데이터가 준비되는 것은 아니에요. 두 경우 모두 이 누락 분기에서는 shadow 채우기까지 가지 않아요.', 'shadow가 있을 때에만 뒤의 __memset으로 검사 상태를 채워요. 조회·없을 때 처리·있을 때 쓰기를 세 단계로 나눠 읽으세요. 이 함수의 반환형은 void이므로 성공 여부를 참·거짓 값으로 돌려주는 함수도 아니에요.'], [('shadow가 없고 checked=false이면 새 검사 정보를 만드나요?', ['네. 새 페이지를 할당해요', '아니요. 이 누락 분기에서는 추가 진단 없이 반환해요'], '정답은 두 번째예요. lookup 실패 뒤 return하며 할당 코드가 없어요. 다만 앞의 연속성 경고 검사는 별개이므로 전체 함수에 경고가 절대 없다는 뜻은 아니에요.'), ('shadow가 없고 checked=true이면 어떤 진단 경로로 가나요?', ['로그와 경고를 남기는 경로예요', '무조건 조용히 성공 처리해요'], '정답은 첫 번째예요. 본문에 pr_err와 KMSAN_WARN_ON(true)가 있어요. 없는 shadow에 성공적으로 썼다는 뜻이 아니며 실제 경고 뒤 실행 여부는 경고 정책도 따라요.')]), 'os1731': ('네 칸짜리 상자 두 개 사이에 걸친 두 칸을 표시하려 해요. 실제 칠할 칸은 둘이지만 관련된 상자는 두 개예요.', '요청 shadow 범위와 원인 그룹 범위를 따로 계산합니다.', '주소103부터2바이트는103·104임을 적고 네 칸 묶음100~103,104~107에 각각 걸치는 그림을 그리세요.', ['이 함수는 먼저 요청한 size만큼 shadow를 채워요. shadow는 데이터의 준비 상태를 나타내는 검사표예요. origin은4바이트 묶음과 연결되는 원인 정보라서 같은 요청이라도 처리할 그룹 범위는 더 넓을 수 있어요.', '주소가4바이트 경계에 맞지 않으면 나머지 pad를 구하고 주소에서 pad를 빼요. 주소103이면103%4=3이므로 pad3, 정렬한 주소는100이에요. 정렬은 여기서 묶음 시작에 맞추는 일이에요.', '길이에도 앞에서 늘어난 pad를 더해요. 원래 길이2이면2+3=5예요. 이어4의 배수로 올리면8이 되므로 원인 범위는100부터8바이트, 즉 두 묶음을 덮어요. 실제 요청 바이트103·104가 각각 다른 묶음에 있기 때문이에요.', '이 정렬 확대는 shadow를 채운 뒤에 해요. 따라서 원인 그룹을 두 개 다룬다고 요청 shadow2바이트 대신8바이트를 먼저 칠하는 코드가 아니에요. 요청 범위와 그룹을 찾기 위한 범위 계산의 순서를 구별하세요.', '새 origin이0이 아니면 조건 origin || !shadow_start[i]의 앞부분이 참이라 해당 origin 슬롯에 저장해요. 새 origin이0이면 shadow_start[i]가0인 경우에만 지워요. 새 원인 저장과 기존 원인 삭제의 조건은 같지 않아요.', '주의해서 읽을 점은 shadow_start가 처음 lookup에서 얻은 u32 포인터라는 사실이에요. 뒤에서 address와 size를 정렬해도 이 포인터를 다시 아래로 정렬하는 대입은 여기 없어요. 그러므로 미정렬 입력에서 읽는 shadow word까지 자동으로 정렬된 그룹과 일치한다고 가정하면 안 돼요. 이 수업의 두 그룹 계산은 원인 대상 범위 계산이며 모든 미정렬 실행의 정확성을 증명하지 않아요.'], [('묶음 안 offset3에서 길이2를 요청하면 원인 범위는 몇 그룹인가요?', ['언제나 한 그룹이에요', '4바이트 그룹 두 개예요'], '정답은 두 번째예요. 앞 pad3을 길이2에 더하면5이고4의 배수로 올리면8이에요. 8/4=2그룹이며 shadow 요청 자체는2바이트예요.'), ('새 origin이0이 아니면 해당 슬롯을 언제 덮나요?', ['이 분기에서는 그 origin을 저장해요', 'shadow word가0일 때에만 저장해요'], '정답은 첫 번째예요. 조건은 origin || !shadow_start[i]이므로 origin이 비영이면 참이에요. shadow가0인지 추가로 요구하는 것은 origin0을 저장해 지우려는 경우예요.')]), 'os1732': ('구역 안의 주소인지 확인한 다음 실제 집의 정보를 찾아요. 첫 구역 검사와 뒤의 조회·확인은 서로 다른 단계예요.', '주소 분류와 페이지 조회·PFN 확인의 순서를 이해합니다.', '범위 밖→NULL, 범위 안→page조회→PFN유효면page·아니면NULL로 흐름을 그리세요.', ['kmsan_vmalloc_to_page_or_null은 정해진 종류의 가상 주소에서 페이지 정보를 얻는 도우미예요. page는 실제 메모리 페이지를 나타내는 커널 자료구조예요. NULL은 여기서 반환할 페이지 정보가 없다는 특별한 포인터 값이에요.', '첫 단계는 vmalloc 주소 범위인지 또는 module 주소 범위인지 확인해요. vmalloc은 커널 가상 메모리 할당 영역과 관련되고 module은 추가 커널 코드 영역과 관련돼요. 두 범위 모두 아니면 바로 NULL을 반환해요.', 'if의 조건에는 !와 &&가 있어요. !는 아니라는 뜻이고 &&는 둘 다라는 뜻이에요. 따라서 vmalloc도 아니고 module도 아닐 때 돌아가요. 둘 중 한 범위에 속하면 다음 조회 단계로 진행해요.', '범위 안이면 vmalloc_to_page(vaddr)로 page를 얻고 page_to_pfn(page)로 물리 페이지 번호인 PFN을 구해요. pfn_valid는 그 번호의 유효성을 확인하는 데 쓰여요. 참이면 page를 돌려주고 거짓이면 NULL을 돌려줘요.', '주소 숫자가 범위 안이라는 것만으로 뒤의 유효성 조건도 참이라고 할 수는 없어요. 같은 범위 안의 예라도 유효 PFN이면 page, 유효하지 않은 PFN이면 NULL이라는 두 결과를 나눠 읽어야 해요.', '이 본문은 vmalloc_to_page의 결과를 page_to_pfn에 바로 넘기며 그 사이에 if(!page) 검사는 없어요. 따라서 임의의 주소나 조회 결과NULL까지 모두 안전하게 처리한다고 일반화하지 마세요. 필요한 페이지 조회 계약을 지키는 호출 상황에서 해석해야 해요. 여기서는 실제 페이지 테이블을 만든 실험이 아니라 코드의 분기 순서를 공부해요.'], [('vmalloc과 module 범위가 둘 다 아니면 페이지 조회를 하나요?', ['네. 모든 포인터를 먼저 조회해요', '아니요. 앞에서NULL을 반환해요'], '정답은 두 번째예요. 두 범위 모두 아니면 첫 if에서 끝나요. vmalloc_to_page는 이 반환 뒤에 있으므로 그 경로에서는 호출되지 않아요.'), ('주소가 범위 안이고 조회한 페이지의 PFN이 유효하지 않으면 무엇을 반환하나요?', ['NULL이에요', '무조건 page예요'], '정답은 첫 번째예요. 주소 분류를 통과해도 pfn_valid가 거짓이면 else에서NULL이에요. 첫 조건의 통과와 마지막 반환 결과를 구별하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_428.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
